from datetime import datetime, timedelta, timezone

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    seconds = nanoseconds // 1_000_000_000
    microseconds = (nanoseconds % 1_000_000_000) // 1_000
    if tz is None:
        return datetime(1970, 1, 1, 0, 0, 0) + timedelta(seconds=seconds, microseconds=microseconds)
    else:
        return (datetime(1970, 1, 1, 0, 0, 0, tzinfo=timezone.utc) + timedelta(seconds=seconds, microseconds=microseconds)).astimezone(tz)

