import functools

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        if maxsize <= 0:
            return func

        cache = OrderedDict()
        usage = {}
        counter = {}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            if key in cache:
                usage[key] += 1
                cache.move_to_end(key)
            else:
                if len(cache) >= maxsize:
                    lfu_keys = [k for k, v in usage.items() if v == min(usage.values())]
                    for k in lfu_keys:
                        if k in cache:
                            del cache[k]
                            del usage[k]
                if key not in usage:
                    usage[key] = 0
                usage[key] += 1
                cache[key] = func(*args, **kwargs)
            return cache[key]

        return wrapper

    return decorator
