from collections import OrderedDict

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        if typed:
            cache = {}
        else:
            cache = OrderedDict()

        # Helper function to update the frequency of a key
        def update_frequency(key):
            if key in cache:
                cache[key][1] += 1
                cache.move_to_end(key)

        # Main function to execute with caching
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            if key in cache:
                update_frequency(key)
                return cache[key][0]
            if len(cache) >= maxsize:
                least_used = next(iter(cache))
                del cache[least_used]
            result = func(*args, **kwargs)
            cache[key] = [result, 1]  # [result, frequency]
            return result

        return wrapper

    return decorator
