def _legacy_mergeOrderings(orderings):
    from collections import defaultdict

    # Create a dictionary to store the positions of each element across orderings
    element_positions = defaultdict(list)
    for i, ordering in enumerate(orderings):
        for j, element in enumerate(ordering):
            element_positions[element].append((i, j))

    # Sort elements based on their first appearance and then by their position in the ordering
    sorted_elements = sorted(element_positions.keys(), key=lambda x: (element_positions[x][0][0], element_positions[x][0][1]))

    # Merge the orderings while preserving the within-ordering order
    result = []
    for element in sorted_elements:
        last_pos = None
        for pos in element_positions[element]:
            if last_pos is None or pos[1] > last_pos:
                result.append(element)
                last_pos = pos[1]

    return result
