def _legacy_mergeOrderings(orderings):
    from collections import defaultdict

    order_map = defaultdict(list)

    for ordering in orderings:
        first_item = ordering[0]
        order_map[first_item].extend(ordering)

    merged_order = []
    seen_items = set()

    for item in sorted(order_map):
        if item not in seen_items:
            merged_order.extend(order_map[item])
            seen_items.update(order_map[item])

    return merged_order

