def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if not hasattr(context, 'error'):
        context.error = {}

    if not hasattr(context, 'value'):
        context.value = {}

    if 'error_E_low' in self.fields:
        context.error['x_low'] = {'index': self.fields.index('error_E_low')}

    if 'error_E_up' in self.fields:
        context.error['x_up'] = {'index': self.fields.index('error_E_up')}

    if 'error_t_low' in self.fields:
        context.error['y_low'] = {'index': self.fields.index('error_t_low')}

    if 'error_t_up' in self.fields:
        context.error['y_up'] = {'index': self.fields.index('error_t_up')}

    if 'error_z_low' in self.fields:
        context.error['z_low'] = {'index': self.fields.index('error_z_low')}

    if 'error_z_up' in self.fields:
        context.error['z_up'] = {'index': self.fields.index('error_z_up')}

    if 'E' in self.fields:
        context.value['x'] = self E

    if 't' in self.fields:
        context.value['y'] = self t

    if 'z' in self.fields:
        context.value['z'] = self z

