def difference(d1, d2, level=-1, current_level=0):
    if level != -1 and current_level >= level:
        return d1
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        else:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_diff = difference(d1[key], d2[key], level, current_level + 1)
                if any(value is not None for value in sub_diff.values()):
                    result[key] = sub_diff
            elif d1[key] != d2[key]:
                result[key] = d1[key]
    return result
