from typing import Dict, List, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages

def _validate_labels(labels: Dict[str, Union[str, List[str]]]) -> None:
    key_regex = r'^[a-zA-Z0-9._-]+$'
    value_regex = r'^[a-zA-Z0-9._-]+$'

    errors = []

    for key, values in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        if not re.match(key_regex, key):
            errors.append({key: "Label key '{}' does not match the regex {}".format(key, key_regex)})

        if isinstance(values, list):
            for value in values:
                if not isinstance(value, str):
                    errors.append({'[' + str(value) + ']': 'expected string or bytes-like object'})
                    continue
                if not re.match(value_regex, value):
                    errors.append({'[' + str(value) + ']': "Label value '{}' does not match the regex {}".format(value, value_regex)})
        else:
            if not isinstance(values, str):
                errors.append({str(values): 'expected string or bytes-like object'})
                continue
            if not re.match(value_regex, values):
                errors.append({values: "Label value '{}' does not match the regex {}".format(values, value_regex)})

    if errors:
        raise ValidationError(messages=errors)

