    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str):
                    errors.append({str(v): 'expected string or bytes-like object'})
                elif not label_value_regex.match(v):
                    errors.append({v: 'Label value does not match the regex'})
        else:
            if not isinstance(value, str):
                errors.append({str(key): 'expected string or bytes-like object'})
            elif not label_value_regex.match(value):
                errors.append({value: 'Label value does not match the regex'})

