def format(
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Replace in-style parameters with out-style parameters
    if isinstance(sql, bytes):
        sql_str = sql.decode()
    else:
        sql_str = sql

    if isinstance(params, Mapping):
        placeholders = [":" + str(k) for k in params.keys()]
    else:
        placeholders = ["%s"] * len(params)

    formatted_sql = sql_str.replace("?", "%s").replace(":param", "%s")

    if isinstance(sql, bytes):
        formatted_sql = formatted_sql.encode()

    if isinstance(params, Mapping):
        converted_params = [params[k] for k in placeholders]
    else:
        converted_params = list(params)

    return formatted_sql, converted_params
