def format(
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, Mapping):
        formatted_sql = sql
        out_style_params = {}
        for param, value in params.items():
            param_str = f"%({param})s"
            formatted_sql = formatted_sql.replace(param_str, f":{param}")
            out_style_params[param] = value
        return formatted_sql, out_style_params
    elif isinstance(params, Sequence):
        formatted_sql = sql
        out_style_params = []
        for i, value in enumerate(params):
            param_str = f"%s"
            formatted_sql = formatted_sql.replace(param_str, f":{i}")
            out_style_params.append(value)
        return formatted_sql, out_style_params
    else:
        raise ValueError("params must be a Mapping or Sequence")

