def formatmany(self, sql, many_params):
    if isinstance(sql, bytes):
        sql_str = sql.decode('utf-8')
    else:
        sql_str = sql

    out_style_params = []
    for params in many_params:
        if isinstance(params, dict):
            out_style_params.append(params)
        else:
            out_style = self.SQLParams.in_style
            if out_style == '{':
                out_style_params.append({f'${i+1}': value for i, value in enumerate(params)})
            elif out_style == ':':
                out_style_params.append({f':{i+1}': value for i, value in enumerate(params)})
            elif out_style == '?':
                out_style_params.append(params)
            else:
                raise ValueError(f"Unsupported parameter style: {out_style}")

    if isinstance(sql_str, bytes):
        out_style_sql = sql.decode('utf-8').format(**{f'{i+1}': param for i, param in enumerate(many_params)})
        return out_style_sql.encode('utf-8'), out_style_params
    else:
        out_style_sql = sql_str.format(**{f'{i+1}': param for i, param in enumerate(many_params)})
        return out_style_sql, out_style_params
