def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Assuming inventory is a dictionary where keys are versions and values are lists of (logical_path, file_path) tuples
    result = {}
    for v, paths in inventory.items():
        if v == version:
            for logical_path, file_path in paths:
                if logical_path in result:
                    result[logical_path].add(file_path)
                else:
                    result[logical_path] = {file_path}
        elif v > version:
            paths_by_logical_path = {}
            for logical_path, file_path in paths:
                if logical_path in paths_by_logical_path:
                    paths_by_logical_path[logical_path].add(file_path)
                else:
                    paths_by_logical_path[logical_path] = {file_path}
            for logical_path, file_paths in paths_by_logical_path.items():
                if logical_path in result:
                    result[logical_path].update(file_paths)
    return result
