def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    allowed_files = set(manifest_files)

    for file_info in fixity.values():
        if not isinstance(file_info, dict):
            raise ValueError("Each file info in fixity block must be a dictionary")
        file_path = file_info.get('path')
        if file_path not in allowed_files:
            raise ValueError(f"File path {file_path} in fixity block is not in the manifest")
        if not isinstance(file_info.get('checksum'), str):
            raise ValueError("Checksum must be a string")
        if not isinstance(file_info.get('algorithm'), str):
            raise ValueError("Checksum algorithm must be a string")

