        namaste_file = os.path.join(path, '0=*')
        if os.path.exists(namaste_file):
            with open(namaste_file, 'r') as f:
                namaste_content = f.read()
                if namaste_content.strip() == "Namaste":
                    return "root" if os.listdir(path) == ["0=*"] else "object"
                else:
                    return "unknown OCFL type"
        else:
            return "directory without Namaste file"

    return "unknown path type"

