def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import ScalarNode, MappingNode, Node

    def deep_merge(dict1, dict2):
        for key in dict2:
            if key in dict1:
                if isinstance(dict1[key], MappingNode) and isinstance(dict2[key], MappingNode):
                    deep_merge(dict1[key].value, dict2[key].value)
                else:
                    dict1[key] = dict2[key]
            else:
                dict1[key] = dict2[key]

    result = []
    seen_keys = set()
    for key, value in nodes:
        key_value_pairs = {}
        seen_keys.add(key.value)
        for item in value.value:
            key_value_pairs[item[0].value] = item[1]
        for key_to_merge, value_to_merge in key_value_pairs.items():
            if key_to_merge in seen_keys:
                found = False
                for i, (existing_key, existing_value) in enumerate(result):
                    if existing_key.value == key.value:
                        deep_merge(existing_value.value, key_value_pairs)
                        found = True
                        break
                if not found:
                    result.append((key, MappingNode(tag='tag:yaml.org,2002:map', value=[(ScalarNode(tag='tag:yaml.org,2002:str', value=key_to_merge), value_to_merge)])))
            else:
                result.append((key, MappingNode(tag='tag:yaml.org,2002:map', value=[(ScalarNode(tag='tag:yaml.org,2002:str', value=key_to_merge), value_to_merge)])))
                seen_keys.add(key_to_merge)
    return result
