from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = "/tmp",
) -> str:
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found at {archive_path}")

    if not filename:
        filename = os.path.basename(archive_path)

    temp_dir = Path(tmp_path) / filename
    temp_dir.mkdir(exist_ok=True)

    if archive_path.endswith('.zip'):
        subprocess.run(["unzip", archive_path, "-d", temp_dir])
    elif archive_path.endswith('.tar'):
        subprocess.run(["tar", "-xvf", archive_path, "-C", temp_dir])
    elif archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        subprocess.run(["tar", "-zxvf", archive_path, "-C", temp_dir])
    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

    repo_url = f"file://{temp_dir}"
    return repo_url
