import os

def _resolve_string(matcher):
    if not matcher.startswith('$'):
        raise ValueError("Matcher must start with '$'")

    parts = matcher[1:].split(':')
    if len(parts) > 2:
        raise ValueError("Invalid matcher format")

    env_name = parts[0]
    default_value = parts[1] if len(parts) == 2 else None

    if env_name in os.environ:
        return os.environ[env_name]
    elif default_value is not None:
        return default_value
    else:
        raise KeyError(f"Environment variable '{env_name}' not set and no default value provided")
