def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).
    """
    if not isinstance(commands, list):
        commands = [commands]

    if args:
        commands.extend(args)

    command_string = ' '.join(commands)

    if verbose:
        print(f"Running command: {command_string}")

    process = subprocess.Popen(
        command_string,
        cwd=cwd,
        shell=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT if hide_stderr else subprocess.PIPE,
        env=env
    )

    output, error = process.communicate()

    if verbose:
        print(f"Command output: {output.decode('utf-8')}")

    if process.returncode != 0:
        print(f"Command failed with error: {error.decode('utf-8') if error else ''}")

    return {
        'returncode': process.returncode,
        'stdout': output.decode('utf-8') if error else '',
        'error': error.decode('utf-8') if error else None
    }

