from typing import Optional, Set
from rdflib import Graph, URIRef, Node

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None
) -> Set[Node]:
    if roots is None:
        roots = set()

    for child in graph.subjects(predicate=prop):
        if not graph.objects(subject=child, predicate=prop):
            roots.add(child)
        else:
            for parent in graph.objects(subject=child, predicate=prop):
                if parent not in roots:
                    roots.add(parent)

    return roots
