def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import logging
    from collections import defaultdict

    def resolve_environment_variables(config):
        if isinstance(config, dict):
            return {k: resolve_environment_variables(v) for k, v in config.items()}
        if isinstance(config, list):
            return [resolve_environment_variables(v) for v in config]
        if isinstance(config, str) and config.startswith('${') and config.endswith('}'):
            env_var = config[2:-1]
            return os.getenv(env_var, config)
        return config

    def parse_config(file_path):
        try:
            with open(file_path, 'r') as file:
                config_data = json.load(file)
            if resolve_env:
                config_data = resolve_environment_variables(config_data)
            return config_data
        except json.JSONDecodeError as e:
            logger.error(f"Error parsing {file_path}: {e}")
            return None

    logger = logging.getLogger(__name__)
    logger.setLevel(logging.ERROR)
    error_records = []

    parsed_configs = defaultdict(dict)
    for filename in config_filenames:
        parsed_config = parse_config(filename)
        if parsed_config is not None:
            parsed_configs[filename] = parsed_config
        else:
            error_record = logging.LogRecord(level=logging.ERROR, pathname=filename, lineno=0, msg=f"Failed to parse {filename}", args=(), exc_info=None)
            error_records.append(error_record)

    if overrides:
        for filename, override_data in overrides.items():
            if filename in parsed_configs:
                parsed_configs[filename].update(resolve_environment_variables(override_data))

    return dict(parsed_configs), error_records
