def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    from configparser import ConfigParser
    import os

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        config = ConfigParser()
        try:
            with open(config_filename, 'r') as file:
                config.read_file(file)
                if overrides:
                    for section in overrides:
                        if section in config:
                            for key, value in overrides[section].items():
                                config[section][key] = value
                if resolve_env:
                    for section in config:
                        for key, value in config[section].items():
                            config[section][key] = os.path.expandvars(value)
                config_dict[config_filename] = dict(config)
        except Exception as e:
            log_record = logging.LogRecord('load_configurations', logging.ERROR, None, None, str(e), None, None)
            log_records.append(log_record)

    return config_dict, log_records
