class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not 0 <= ticks < 86400000000000:
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        seconds = ticks // 10**9
        microseconds = (ticks % 10**9) // 1000

        dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=seconds, microseconds=microseconds)
        if tz:
            dt = dt.replace(tzinfo=tz)

        return cls(dt)

    def __init__(self, dt):
        self._dt = dt

    def __repr__(self):
        return f"Time({self._dt})"

    def __eq__(self, other):
        if not isinstance(other, Time):
            return NotImplemented
        return self._dt == other._dt
