def scale(self, other=None, recompute=False):
    if other is None:
        if hasattr(self, 'scale') and not recompute:
            return self.scale
        else:
            self.scale = sum(self.data)
            return self.scale
    elif isinstance(other, float) and other != 0:
        if hasattr(self, 'scale') and self.scale != 0:
            factor = other / self.scale
            self.data = [x * factor for x in self.data]
            self.scale = other
