def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid("Candidate does not claim to provide the interface")

    defined_methods = set(dir(candidate))
    required_methods = set(iface.names())

    if not required_methods.issubset(defined_methods):
        missing_methods = required_methods - defined_methods
        if len(missing_methods) == 1:
            raise Invalid(f"Method {missing_methods.pop()} is missing")
        else:
            raise Invalid(f"Missing methods: {missing_methods}")

    for method in required_methods:
        candidate_method = getattr(candidate, method)
        if not callable(candidate_method):
            raise Invalid(f"{method} is not a callable method")

    defined_attributes = set(dir(candidate))
    required_attributes = set(iface.attributions())

    if not required_attributes.issubset(defined_attributes):
        missing_attributes = required_attributes - defined_attributes
        if len(missing_attributes) == 1:
            raise Invalid(f"Attribute {missing_attributes.pop()} is missing")
        else:
            raise Invalid(f"Missing attributes: {missing_attributes}")

    return True

