def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import verify, Invalid

    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"Candidate does not explicitly implement {iface}")

    method_signatures = iface.getMethods()
    attribute_names = iface.getAttributes()

    verification_errors = []

    for method_name, method_info in method_signatures.items():
        method = getattr(candidate, method_name, None)
        if method is None:
            verification_errors.append(f"Method {method_name} is not defined")
        else:
            sig = inspect.signature(method)
            if str(sig) != str(inspect.signature(method_info)):
                verification_errors.append(f"Method {method_name} does not have the correct signature")

    for attribute_name in attribute_names:
        if not hasattr(candidate, attribute_name):
            verification_errors.append(f"Attribute {attribute_name} is not defined")

    if verification_errors:
        if len(verification_errors) == 1:
            raise Invalid(verification_errors[0])
        else:
            raise Invalid("\n".join(verification_errors))

    return True

