    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    original_text = text
    replaced_text = ""
    i = 0

    while i < len(text):
        if not in_code_block:
            if text.startswith("<", i) and text.endswith(">", i+len("<tag>")):
                tag = text[i+1:i+len("<tag>")]
                tags.add(tag)
                if replacer:
                    replaced_text += replacer(tag)
                else:
                    replaced_text += tag
                i += len("<tag>")
            elif text.startswith("<", i) and text.endswith("/>", i+len("<tag/")):
                i += len("<tag/>")
            else:
                replaced_text += text[i]
                i += 1
        else:
            if text.startswith("```", i):
                in_code_block = False
                i += len("```")
            else:
                replaced_text += text[i]
                i += 1

    if in_code_block:
        replaced_text += text[i:]

    return tags, replaced_text
