def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    from typing import Set, Tuple

    def is_code_block(tag_start: str, text: str) -> bool:
        code_block_end = f"\n{' ' * tag_start.count(' ')}\n"  # Adjust for indentation
        return code_block_end in text

    tags = set()
    in_code_block = False
    i = 0

    while i < len(text):
        if text[i:i+2] == "<=":
            i += 2
            continue  # Skip over "<=" operator
        elif text[i:i+3] == "<!--":
            while i < len(text) and text[i:i+3] != "-->":
                i += 1
            i += 2  # Move beyond "-->"
            continue
        elif text[i:i+2] == "<!":
            while i < len(text) and text[i] != ">":
                i += 1
            i += 1  # Move beyond ">"
            continue
        elif text[i:i+4] == "<pre":
            in_code_block = True
            while i < len(text) and text[i:i+5] != "\n</pre":
                i += 1
            i += 4  # Move beyond "\n</pre"
            continue
        elif text[i:i+2] == "</":
            in_code_block = False
            while i < len(text) and text[i] != ">":
                i += 1
            i += 1  # Move beyond ">"
            continue
        elif text[i] == "@" and text[i+1] == "@":
            tag_start = i
            i += 2
            while i < len(text) and text[i] != "@":
                i += 1
            tag_end = i
            if not in_code_block or not is_code_block(tag_start, text):
                tag_word = text[tag_start+2:tag_end]
                tags.add(tag_word)
                if replacer:
                    text = text[:tag_start] + replacer(tag_word) + text[tag_end:]
                i = tag_end  # Move beyond the tag word

        i += 1

    return tags, text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    result = []
    for line in text.split('\n'):
        if line.strip().startswith('```') or line.strip().endswith('```'):
            in_code_block = not in_code_block
            result.append(line)
            continue
        if not in_code_block:
            parts = line.split()
            for part in parts:
                if part.startswith('#') and not part.startswith('#:'):
                    tag = part[1:]
                    tags.add(tag)
                    if replacer:
                        part = replacer(tag)
                    result.append(part + ' ')
                else:
                    result.append(part + ' ')
        else:
            result.append(line)
            continue
    return tags, ' '.join(result).strip()

