def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    result = ""
    current_tag = ""

    for char in text:
        if char == "`" and not in_code_block:
            in_code_block = True
        elif char == "`" and in_code_block:
            in_code_block = False
        elif not in_code_block:
            if char == "@":
                current_tag += char
            elif current_tag:
                current_tag += char
                if char == " ":
                    tags.add(current_tag.strip("@"))
                    current_tag = ""
            else:
                result += char

    if current_tag:
        tags.add(current_tag.strip("@"))

    if replacer:
        result = replacer(result)

    return tags, result
