        'int': int,
        'float': float,
        'bool': lambda v: v.lower() in ('true', '1', 't', 'y', 'yes'),
        # Add more type conversions as needed
    }

    for key, value in values_dict.items():
        if value.isdigit():
            values_dict[key] = int(value)
        elif '.' in value:
            values_dict[key] = float(value)
        elif value.lower() in ('true', 'false', '1', '0', 't', 'f', 'y', 'n', 'yes', 'no'):
            values_dict[key] = value.lower() in ('true', '1', 't', 'y', 'yes')
        else:
            for converter_type, converter in type_mapping.items():
